import unittest
from unittest.mock import patch
from candidate import largest_prime_factor

class TestLargestPrimeFactor(unittest.TestCase):
    def test_largest_prime_factor_with_odd_number(self):
        self.assertEqual(largest_prime_factor(13195), 29)

    def test_largest_prime_factor_with_power_of_2(self):
        self.assertEqual(largest_prime_factor(2048), 2)

    def test_largest_prime_factor_with_prime(self):
        with patch('candidate.is_prime', side_effect=lambda x: x == 2 or x == 3 or x == 5 or x == 7):
            self.assertEqual(largest_prime_factor(15), 5)

    def test_largest_prime_factor_with_composite_number(self):
        self.assertEqual(largest_prime_factor(13195), 29)

    def test_largest_prime_factor_with_even_number(self):
        self.assertEqual(largest_prime_factor(600851562777595), 6857)

    def test_largest_prime_factor_with_smallest_input(self):
        self.assertEqual(largest_prime_factor(2), 2)

    def test_largest_prime_factor_with_none_input(self):
        with self.assertRaises(TypeError):
            largest_prime_factor(None)

    def test_largest_prime_factor_with_empty_input(self):
        with self.assertRaises(TypeError):
            largest_prime_factor("")

    def test_largest_prime_factor_with_non_integer_input(self):
        with self.assertRaises(TypeError):
            largest_prime_factor(2.5)

    def test_largest_prime_factor_with_negative_input(self):
        with self.assertRaises(TypeError):
            largest_prime_factor(-10)

    def test_largest_prime_factor_with_zero_input(self):
        with self.assertRaises(ValueError):
            largest_prime_factor(0)

    def test_largest_prime_factor_with_invalid_input_type(self):
        with self.assertRaises(TypeError):
            largest_prime_factor([1, 2, 3])

if __name__ == '__main__':
    unittest.main()
